INSERT IGNORE INTO hidden_careers (title, description, why_hidden, discovery_tip, category, average_salary, required_skills, curiosity_score) VALUES
('Prompt Engineer', 'Design and optimize prompts for AI language models to get precise, reliable outputs for products.', 'Too new to appear in career counseling most schools have no idea this role exists yet.', 'Start with OpenAI Playground. Build a portfolio of prompt systems. Follow AI researchers on Twitter.', 'Tech & Digital', '$130,000', 'Python, NLP, Critical Thinking, LLMs, Communication', 31),
('Forensic Accountant', 'Investigate financial fraud, embezzlement, and white-collar crime using accounting and investigation skills.', 'Schools teach accounting for business the crime investigation angle is invisible to most students.', 'Study accounting and take a forensic investigation course. Look for internships at audit firms or law enforcement.', 'Business & Management', '$95,000', 'Accounting, Fraud Detection, Law, Excel, Attention to Detail', 18),
('Science Communicator', 'Translate complex scientific research into content the general public can understand, care about, and act on.', 'Scientists rarely discuss careers bridging science and media this barely appears in career counseling.', 'Start a blog or YouTube channel explaining one scientific concept per week. Build a portfolio of clear explanations.', 'Creative & Media', '$70,000', 'Writing, Science Background, Storytelling, Video Production, Social Media', 22),
('Urban Farmer', 'Grow food in city environments using vertical farms, rooftops, and hydroponic technology systems.', 'Agriculture is seen as rural and old-fashioned urban farming as a tech-forward business is virtually unknown.', 'Visit a local urban farm or hydroponics setup. Take a permaculture course online. Start with a small balcony system.', 'Science & Health', '$60,000', 'Horticulture, Business, Sustainability, Technology, Community Building', 9),
('Esports Coach', 'Train competitive gaming teams and individual players to improve performance, strategy, and mental resilience.', 'Gaming careers are dismissed as hobbies professional esports coaching is a legitimate and growing profession.', 'Start coaching friends or local teams. Build a coaching portfolio. Network in Discord communities and esports forums.', 'Social & Specialized', '$65,000', 'Game Mastery, Strategy, Communication, Psychology, Analysis, Leadership', 35),
('Conversational AI Designer', 'Design the personality, dialogue flows, and responses of chatbots and AI voice assistants.', 'Exists at the intersection of psychology, writing, and tech almost no school talks about this role.', 'Study linguistics and UX writing. Build chatbots using Dialogflow or Rasa. Create sample conversation flows.', 'Tech & Digital', '$95,000', 'Linguistics, UX Writing, Psychology, Chatbot Platforms, Empathy, Logic', 27),
('Biohacker', 'Use science, technology, and self-experimentation to optimize human performance, health, and longevity.', 'Exists outside traditional academia and medicine most career advisors have never heard of it.', 'Follow biohacking communities. Start with sleep, nutrition, and exercise optimization. Read research papers.', 'Science & Health', '$70,000', 'Biology, Self-Experimentation, Research, Nutrition, Technology, Data Tracking', 41),
('Music Supervisor', 'Select and license music for films, TV shows, games, and advertisements to enhance emotional storytelling.', 'Everyone knows music producers but nobody talks about the person who places music in your favorite shows.', 'Build a playlist portfolio matching moods to scenes. Network with indie filmmakers. Study music licensing basics.', 'Creative & Media', '$80,000', 'Music Knowledge, Licensing Law, Negotiation, Networking, Storytelling, Taste', 16);